'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var accessors = require( './accessors.js' );


// MAIN //

/**
* Returns the index of the n-th occurrence of a specified search element in a strided array using alternative indexing semantics.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {PositiveInteger} k - occurrence number
* @param {*} searchElement - search element
* @param {Collection} x - input array
* @param {integer} strideX - stride length
* @param {NonNegativeInteger} offsetX - starting index
* @returns {integer} index
*
* @example
* var x = [ 1.0, -2.0, 3.0, -5.0, 3.0, 4.0, -1.0, 3.0 ];
*
* var idx = gnthIndexOf( x.length, 2, 3.0, x, 1, 0 );
* // returns 4
*/
function gnthIndexOf( N, k, searchElement, x, strideX, offsetX ) {
	var ix;
	var n;
	var o;
	var i;

	if ( N <= 0 || k <= 0 ) {
		return -1;
	}
	o = arraylike2object( x );
	if ( o.accessorProtocol ) {
		return accessors( N, k, searchElement, o, strideX, offsetX );
	}
	n = 0;
	ix = offsetX;
	for ( i = 0; i < N; i++ ) {
		if ( x[ ix ] === searchElement ) {
			n += 1;
			if ( n === k ) {
				return i;
			}
		}
		ix += strideX;
	}
	return -1;
}


// EXPORTS //

module.exports = gnthIndexOf;
